def tile_info(y0,x0):
    # 6x6 subgrid, return compact string of non-background color distribution
    from collections import Counter
    cnt=Counter()
    shape=[]
    for r in range(y0,y0+6):
        line=''
        for c in range(x0,x0+6):
            v=grid[r][c]
            cnt[v]+=1
            if v==5: line+='.'
            else: line+=f'{v:x}'
        shape.append(line)
    # return count summary and if uniform return color
    if len(cnt)==1 and 5 in cnt:
        return 'empty'
    if len(cnt)==1:
        k=list(cnt)[0]
        return f'uni{k}'
    # else pattern
    return 'pat '+','.join(f'{k}:{cnt[k]}' for k in sorted(cnt)) + '\n' + '\n'.join(shape)

